import shutil
import openpyxl
from openpyxl.styles import Font, Alignment

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def clean_text(v):
    if v is None:
        return None
    s = str(v).strip()
    if s in ("", "-"):
        return None
    return s

def to_num(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip()
    if s in ("", "-"):
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0

def display_num(v):
    if v is None:
        return "-"
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        if v == 0:
            return "-"
        if float(v).is_integer():
            return int(v)
        return v
    s = str(v).strip()
    if s in ("", "-"):
        return "-"
    return s

def display_text(v):
    if v is None:
        return "-"
    s = str(v).strip()
    if s in ("", "-"):
        return "-"
    return s

agg = {}
first_seen = {}
order = 0
for sheet in vals.sheetnames:
    if sheet.strip().upper() == "COLLECTION":
        continue
    vws = vals[sheet]
    headers = {}
    for col in range(1, vws.max_column + 1):
        h = vws.cell(row=1, column=col).value
        if h is not None:
            headers[str(h).strip().upper()] = col
    c_ty = headers.get("TY")
    c_or = headers.get("OR")
    c_sale = headers.get("SALE")
    c_ret = headers.get("RET")
    c_br = headers.get("BR")
    for r in range(2, vws.max_row + 1):
        if c_ty is None or c_or is None:
            continue
        ty = clean_text(vws.cell(row=r, column=c_ty).value)
        orr = clean_text(vws.cell(row=r, column=c_or).value)
        if ty is None or orr is None:
            continue
        key = (ty, orr)
        if key not in agg:
            agg[key] = {"sale": 0.0, "ret": 0.0, "br": None}
            first_seen[key] = order
            order += 1
        if c_sale is not None:
            agg[key]["sale"] += to_num(vws.cell(row=r, column=c_sale).value)
        if c_ret is not None:
            agg[key]["ret"] += to_num(vws.cell(row=r, column=c_ret).value)
        if c_br is not None and agg[key]["br"] is None:
            br = clean_text(vws.cell(row=r, column=c_br).value)
            if br is not None:
                agg[key]["br"] = br

if "COLLECTION" not in wb.sheetnames:
    ws = wb.create_sheet("COLLECTION")
else:
    ws = wb["COLLECTION"]

vws = vals["COLLECTION"] if "COLLECTION" in vals.sheetnames else None
existing = []
existing_keys = set()
max_item = 0
if vws is not None:
    for r in range(2, vws.max_row + 1):
        a = vws.cell(row=r, column=1).value
        b = vws.cell(row=r, column=2).value
        c = vws.cell(row=r, column=3).value
        d = vws.cell(row=r, column=4).value
        e = vws.cell(row=r, column=5).value
        f = vws.cell(row=r, column=6).value
        if all(v is None or str(v).strip() in ("", "-") for v in (a, b, c, d, e, f)):
            continue
        key = (clean_text(c), clean_text(d))
        if key[0] is None and key[1] is None:
            continue
        existing_keys.add(key)
        if isinstance(a, (int, float)) and not isinstance(a, bool):
            max_item = max(max_item, int(a))
        existing.append({"key": key, "a": a, "b": b, "c": c, "d": d, "e": e, "f": f})

rows = []
for ex in existing:
    key = ex["key"]
    if key in agg:
        sale = agg[key]["sale"]
        ret = agg[key]["ret"]
    else:
        sale = to_num(ex["e"])
        ret = to_num(ex["f"])
    bal = sale - ret
    rows.append([ex["a"], ex["b"], ex["c"], ex["d"], sale, ret, bal])

missing = [k for k in agg if k not in existing_keys]
missing.sort(key=lambda k: first_seen[k])
next_item = max_item + 1
for key in missing:
    ty, orr = key
    br = agg[key]["br"]
    sale = agg[key]["sale"]
    ret = agg[key]["ret"]
    bal = sale - ret
    rows.append([next_item, br, ty, orr, sale, ret, bal])
    next_item += 1

answer_rows = rows[:8]

for r in range(2, 10):
    for col in range(1, 8):
        ws.cell(row=r, column=col).value = None

for i, row in enumerate(answer_rows):
    r = 2 + i
    for col, val in enumerate(row, start=1):
        cell = ws.cell(row=r, column=col)
        if col == 1:
            if val is None:
                cell.value = None
            elif isinstance(val, (int, float)) and not isinstance(val, bool):
                cell.value = int(val) if float(val).is_integer() else val
            else:
                cell.value = str(val).strip()
        elif col in (2, 3, 4):
            cell.value = display_text(val)
        else:
            cell.value = display_num(val)

for col in range(1, 8):
    cell = ws.cell(row=1, column=col)
    cell.font = Font(name="Calibri", size=11, bold=False, color="FF000000")
    cell.alignment = Alignment(horizontal="left")

for r in range(2, 10):
    for col in range(1, 8):
        cell = ws.cell(row=r, column=col)
        v = cell.value
        negative = isinstance(v, (int, float)) and not isinstance(v, bool) and v < 0
        color = "FFFF0000" if negative else "FF000000"
        cell.font = Font(name="Calibri", size=11, bold=False, color=color)
        if col in (1, 5, 6, 7):
            cell.alignment = Alignment(horizontal="right")
        else:
            cell.alignment = Alignment(horizontal="left")

wb.save(OUT)
print("answer_rows:", len(answer_rows))
for row in answer_rows:
    print(row)
